}

void converter_t::convert(std::string& value) {
  if (write) {
    // serialization length validation
    cb_assert(value.length() <= SHRT_MAX);
  }

  short value_size = (short)value.length();
  convert(value_size);

  if (write) {
    if (pointer) memmove(current(), value.data(), value_size);
  } else {
    if (value_size < 0) {
      set_error();
      return;
    }  // deserialization length validation

    if (is_error() || !at_least(value_size)) {
      set_error();
      return;
    }
    value.resize(value_size);
    memmove(value.data(), current(), value_size);
  }
  forward(value_size);
}

converter_t::converter_t(bool _write) : write(_write), rv_error(0), pointer(nullptr), offset(0), size(0) {}

converter_t::converter_t(byte_ptr out) : write(true), rv_error(0), pointer(out), offset(0), size(0) {}

converter_t::converter_t(mem_t src)
    : write(false), rv_error(0), pointer(const_cast<byte_ptr>(src.data)), offset(0), size(src.size) {}

void converter_t::set_error() {
  if (rv_error) return;
  rv_error = coinbase::error(E_FORMAT, "Converter error" + std::string(write ? "(write)" : "(read)"));
}

void converter_t::set_error(error_t rv) {
  if (rv_error) return;
  rv_error = coinbase::error(rv);
}

void converter_t::convert_len(uint32_t& len) {
  byte_t b = 0;
  if (write) {
    cb_assert(len <= MAX_CONVERT_LEN);
    if (len <= 0x7f) {
      b = byte_t(len);
      convert(b);
      return;
    }
    if (len <= 0x3fff) {
      b = byte_t(len >> 8) | 0x80;
      convert(b);
      b = byte_t(len);
      convert(b);
      return;
    }
    if (len <= 0x1fffff) {
      b = byte_t(len >> 16) | 0xc0;
      convert(b);
      b = byte_t(len >> 8);
      convert(b);
      b = byte_t(len);
      convert(b);
      return;
    }
    b = byte_t(len >> 24) | 0xe0;
    convert(b);
    b = byte_t(len >> 16);
    convert(b);
    b = byte_t(len >> 8);
    convert(b);
    b = byte_t(len);
    convert(b);
  } else {
    convert(b);
    if (is_error()) {
      len = 0;
      return;
    }
    if ((b & 0x80) == 0) {
      len = b;
      if (len > MAX_CONVERT_LEN) {
        set_error();
        len = 0;
      }
      return;
    }
    if ((b & 0x40) == 0) {
      len = b & 0x3f;
      convert(b);
      len = (len << 8) | b;
      if (is_error())
        len = 0;
      else if (len > MAX_CONVERT_LEN) {
        set_error();
        len = 0;
      }
      return;
    }
    if ((b & 0x20) == 0) {
      len = b & 0x1f;
      convert(b);
      len = (len << 8) | b;
      convert(b);
      len = (len << 8) | b;
      if (is_error())
        len = 0;
      else if (len > MAX_CONVERT_LEN) {
        set_error();
        len = 0;
      }
      return;
    }
    len = b & 0x1f;
    convert(b);
    len = (len << 8) | b;
    convert(b);
    len = (len << 8) | b;
    convert(b);
    len = (len << 8) | b;
    if (is_error())
      len = 0;
    else if (len > MAX_CONVERT_LEN) {
      set_error();
      len = 0;
    }
  }
}

void converter_t::convert(std::vector<bool>& value) {
  if (!write) value.clear();

  short count = (short)value.size();
  convert(count);

  if (!write) {
    if (count < 0 || static_cast<uint32_t>(count) > MAX_CONTAINER_ELEMENTS) {
      set_error();
      return;
    }
    value.resize(count);
  }
  for (short i = 0; i < count && !is_error(); i++) {
    bool v = value[i];
    convert(v);
    value[i] = v;
  }
}

uint64_t converter_t::convert_code_type(uint64_t code, uint64_t code2, uint64_t code3, uint64_t code4, uint64_t code5,
                                        uint64_t code6, uint64_t code7, uint64_t code8) {
  uint64_t value = code;
  convert(value);
  if (is_error()) return 0;
  if (!write) {
    if (value == code) return value;
    if (code2 && value == code2) return value;
    if (code3 && value == code3) return value;
    if (code4 && value == code4) return value;
    if (code5 && value == code5) return value;
    if (code6 && value == code6) return value;
    if (code7 && value == code7) return value;
    if (code8 && value == code8) return value;
    set_error();
    return 0;
  }
  return value;
}

